#include <iostream>
#include <vector>
#include <algorithm>
#include <set>

using namespace std;

#define int long long

long long base_numbers[1000005];
long long digit_store[1000005];
long long toggle_flags[1000005];
long long temp_store[1000005];
long long answer=1e18;

void evaluate()
{
    for (int i=0; i<18; i++)
    {
        digit_store[i]=temp_store[i];
    }
    for (int i=0; i<17; i++)
    {
        if (toggle_flags[i]>0)
        {
            digit_store[i+1]++;
            digit_store[i]-=10;
            digit_store[0]--;
        }
    }
    if (digit_store[0]<-6)
    {
        digit_store[0]+=11;
        digit_store[1]--;
    }
    if (digit_store[0]>6)
    {
        digit_store[0]-=11;
        digit_store[1]++;
    }
    long long total_score=0;
    for (int i=0; i<18; i++)
    {
        total_score+=abs(digit_store[i])*(i+1);
    }
    answer=min(answer,total_score);
}

void recurse(int idx)
{
    if (idx>=17)
    {
        evaluate();
        return;
    }
    for (int v=0; v<=1; v++)
    {
        toggle_flags[idx]=v;
        recurse(idx+1);
    }
}

int main()
{
    int n;
    cin>>n;
    base_numbers[0]=1;
    for (int i=1; i<18; i++)
    {
        base_numbers[i]=base_numbers[i-1]*10+1;
    }
    int current=n;
    int position=17;
    while (current>0)
    {
        temp_store[position]=current/base_numbers[position];
        current%=base_numbers[position];
        position--;
    }
    recurse(0);
    cout<<answer;
}
